// Build URL from variables, update for each dashboard
const url = `${control_url}/rti/collector_service/rest1/logging:get_collection_level?application_selector=${application_name}`;

/*
 * This function will create the request header
 *
 * Note: Should not need to be modified for each dashboard
 */
function createHeaders(authentication) {

  const authArray = authentication.split(":")
  const headers = new Headers()

  headers.append('Content-Type', 'application/json')
  if (authArray.length === 2) {
    console.log("Adding authorization header")
    headers.append(authArray[0], authArray[1])
  }

  return headers
}

/*
 * This function will process the fetch response
 *
 * Note: Custom implementation for each dashboard
 */
function processResponse(jsonRsp) {
  // create empty initial value object
  let init = {};
  // iterate over each log configuration
  jsonRsp.forEach((logCfg) => {
    // check to see if this configuration matches the $applicationName we requested
    // this assumes that there will only be a single entry that matches the $applicationName
    if (logCfg['application'] === '${application_name}') {
      // iterate over settings and save locally
      logCfg['logging_settings'].forEach((setting) => {
        if (setting['facility'] === 'MIDDLEWARE') {
          init['middlewareCollectionVerbosity'] = setting['verbosity'];
        }
        if (setting['facility'] === 'SECURITY_EVENT') {
          init['securityEventCollectionVerbosity'] = setting['verbosity'];
        }
        if (setting['facility'] === 'USER') {
          init['userCollectionVerbosity'] = setting['verbosity'];
        }
        if (setting['facility'] === 'SERVICE') {
          init['serviceCollectionVerbosity'] = setting['verbosity'];
        }
        console.log("Setting " + setting['facility'] + ":" + setting['verbosity']);
      });
    }
  });

  return init;
}

/*
 * This function will set the server status message for the dashboard and hide the panel elements.
 *
 * Note: Should not need to be modified for each dashboard
 */
function disablePlugin() {
  // create empty initial value object
  let init = {};
  // Set the value for 'serverStatus panel element. This value will hide the other elements
  init['serverStatus'] = 'NOT AVAILABLE';
  // update the "initial" values so the plugin logic works
  setInitial(init);

  // update the server status dashboard variables
  locationService.partial({ 'var-server_status': 'NOT AVAILABLE' }, true);
  locationService.partial({ 'var-server_message': 'Configuration changes can NOT be made!' }, true);

  // Update element values so they match the initial values
  onChange(elements.map((element) => ({
    ...element,
    value: init[element.id],
  })));

  // notify of options update
  onOptionsChange(options);
}

/*
 * This function will handle errors caught in the fetch request
 *
 * Note: Should not need to be modified for each dashboard
 */
function handleError(error) {
  if (error.name === 'TypeError') {
    // could get here because ERR_CONNECTION_REFUSED 
    // could get here because ERR_NAME_NOT_RESOLVED 
    console.log('fetch() failed to access the server.');
    notifyError(['Initialize', 'Server not found or request refused.']);
  } else if (error.name === 'AbortError') {
    console.log('The fetch()() operation timed out');
    notifyError(['Initialize', 'Request timed out.']);
  } else {
    console.log('fetch() failed');
    console.log(error);
    notifyError(['Initialize', 'Unknown failure.']);
  }
}

/*
 * This function will send an HTTP query to get the forwarding verbosity
 *
 * Note: Should not need to be modified for each dashboard
 */
async function getInitializationData() {
  console.log("getInitializationData()");

  const timeout = 3000;
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeout);
  const reqHeaders = createHeaders(`${authentication_header}`);

  fetch(url, {
    method: 'GET',
    headers: reqHeaders,
    signal: controller.signal
  })
    .then(async response => {
      const responseJson = await response.json();
      if (response.ok) {
        console.log("getInitializationData() - response.ok");

        // clear the abort controller
        clearTimeout(id);

        // process the fetch response into the init struct
        let init = processResponse(responseJson);
        // Set the value for 'serverStatus panel element. This value will enable the other elements
        init['serverStatus'] = 'AVAILABLE';

        // update the "initial" values so the plugin logic works
        setInitial(init);

        // update the server status dashboard variables
        locationService.partial({ 'var-server_status': 'AVAILABLE' }, true);
        locationService.partial({ 'var-server_message': 'Configuration changes can be made.' }, true);

        // Update element values so they match the initial values
        onChange(elements.map((element) => ({
          ...element,
          value: init[element.id],
        })));

        // notify of options update
        onOptionsChange(options);

        notifySuccess(['Initialize', 'Data initialized successfully.']);
      } else {
        console.log(`getInitializationData() - fetch() operation returned ${response.status}.`);
        if (response.status === 501) {
          notifyWarning([responseJson['code'], responseJson['message']]);
        } else {
          notifyError([responseJson['code'], responseJson['message']]);
        }
        // the request failed, disable the plugin functionality
        disablePlugin();
      }
    })
    .catch(error => {
      handleError(error);
      // the request failed, disable the plugin functionality
      disablePlugin();
    });
}

getInitializationData();

