      element.value === initial[element.id]) {
      return;
    }

    // if we get here the current element was modified so create setting
    // object and add it to the loggingSettings
    let setting = {}
    switch (element.id) {
      case 'middlewareCollectionVerbosity':
        setting['facility'] = "MIDDLEWARE";
        setting[`verbosity`] = element.value;
        loggingSettings.push(setting);
        break;
      case 'securityEventCollectionVerbosity':
        setting['facility'] = "SECURITY_EVENT";
        setting[`verbosity`] = element.value;
        loggingSettings.push(setting);
        break;
      case 'userCollectionVerbosity':
        setting['facility'] = "USER";
        setting[`verbosity`] = element.value;
        loggingSettings.push(setting);
        break;
      case 'serviceCollectionVerbosity':
        setting['facility'] = "SERVICE";
        setting[`verbosity`] = element.value;
        loggingSettings.push(setting);
        break;
    }
  });

  // create the logSettingEntry object
  let logSettingEntry = {};
  logSettingEntry['application_selector'] = "${application_name}";
  logSettingEntry['logging_settings'] = loggingSettings;
  // add the logSettingEntry object to the body
  body.push(logSettingEntry);

  return body
}

/*
 * This function will handle errors caught in the fetch request
 *
 * Note: Should not need to be modified for each dashboard
 */
function handleError(error) {
  if (error.name === 'TypeError') {
    // could get here because ERR_CONNECTION_REFUSED 
